import type { DatabaseManager, Repository, RepositoryPolicy } from '@nocobase/db';

export class ServiceRepositories {
  constructor(
    private readonly database: DatabaseManager,
    private readonly authorization: AppAuthorization,
  ) {}

  /** A repository bound to one composite action of one business resource. */
  async scoped<TRecord extends object>(
    context: AuthorizationContext,
    resource: string,
    action: string,
    collection: string,
  ): Promise<Repository<TRecord>> {
    const policy = await this.authorization.database.policyFor(collection, context, {
      resource,
      action,
    });
    return this.bind<TRecord>(collection, policy);
  }

  /** An unrestricted repository, for side effects the caller has already authorized. */
  unrestricted<TRecord extends object>(collection: string): Repository<TRecord> {
    return this.database.repository<TRecord>(collection);
  }

  bind<TRecord extends object>(collection: string, policy: RepositoryPolicy): Repository<TRecord> {
    return this.database
      .repository<TRecord>(collection)
      .withPolicy(policy as RepositoryPolicy<TRecord>) as unknown as Repository<TRecord>;
  }
}
